      setErrors(validationErrors);
      const firstErrorField = Object.keys(validationErrors)[0];
      setTimeout(() => {
        document.getElementById(firstErrorField)?.focus();
      }, 0);
    } else {
      setErrors({});
      setIsSubmitted(true);
    }
  };

  if (isSubmitted) {
    return (
