', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-react--style-dark--validation-message-absent/google/gemini-3-flash-preview__s1/script.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { useState, useEffect } = React;

const FormField = ({ label, id, type = "text", required, autocomplete, helperText, value, onChange, error }) => {
  const helperId = helperText ? `${id}-helper` : null;
  const errorId = error ? `${id}-error` : null;
  // If there's an error, we prioritize the error message for AT, 
  // but keeping both is fine.
  const descriptionIds = [errorId, helperId].filter(Boolean).join(" ");

  return (
    <div className="form-field">
      <label htmlFor={id}>
        {label}
        {required && <span className="required-indicator" aria-hidden="true">*</span>}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        required={required}
        autoComplete={autocomplete}
        value={value}
        onChange={onChange}
        aria-describedby={descriptionIds || undefined}
        aria-invalid={!!error}
      />
      {helperText && (
        <div id={helperId} className="helper-text">
          {helperText}
        </div>
      )}
      {error && (
        <div id={errorId} className="error-message">
          {error}
        </div>
      )}
    </div>
  );
};

const ContactForm = () => {
  const [formData, setFormData] = useState({
    fullName: "",
    email: "",
    phone: ""
  });
  const [errors, setErrors] = useState({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[name];
        return newErrors;
      });
    }
  };

  const validate = () => {
    const newErrors = {};
    if (!formData.fullName.trim()) {
      newErrors.fullName = "Error: Full name is required.";
    }
    if (!formData.email.trim()) {
      newErrors.email = "Error: Email address is required.";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = "Error: Please enter a valid email address.";
    }
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();

    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      const firstErrorField = Object.keys(validationErrors)[0];
      setTimeout(() => {
        document.getElementById(firstErrorField)?.focus();
      }, 0);
    } else {
      setErrors({});
      setIsSubmitted(true);
    }
  };

  if (isSubmitted) {
    return (
      <div className="submission-success" role="status">
        <h2>Thank you!</h2>
        <p>Your support request has been sent successfully. We'll get back to you soon.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <FormField
        label="Full Name"
        id="fullName"
        required={true}
        autocomplete="name"
        value={formData.fullName}
        onChange={handleChange}
        error={errors.fullName}
      />
      <FormField
        label="Email Address"
        id="email"
        type="email"
        required={true}
        autocomplete="email"
        value={formData.email}
        onChange={handleChange}
        error={errors.email}
      />
      <FormField
        label="Phone Number"
        id="phone"
        type="tel"
        required={false}
        autocomplete="tel"
        helperText="Format: (XXX) XXX-XXXX"
        value={formData.phone}
        onChange={handleChange}
        error={errors.phone}
      />
      <button type="submit">Send Support Request</button>
    </form>
  );
};

const App = () => {
  return (
    <div className="container">
      <header>
        <h1>Contact Support</h1>
      </header>
      <main>
        <ContactForm />
      </main>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
